int n, m;
vector<pair<int, int>> edges;

bool isCompatible(const vector<int>& labels, const vector<int>& chosen) {
    vector<bitset<7>> used(7); // used[from][to] = whether domino (from, to) is used
    for (int i = 0; i < m; ++i) {
        if (!chosen[i]) continue;
        int u = edges[i].first;
        int v = edges[i].second;
        int a = labels[u];
        int b = labels[v];
        if (a > b) swap(a, b);
        if (used[a][b]) return false;
        used[a][b] = 1;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    edges.resize(m);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        edges[i] = {u, v};
    }

    if (m == 0) {
        cout << 0 << "\n";
        return 0;
    }

    int best = 0;
    // Assign labels 1..6 to vertices (0..5 internal)
    vector<int> labels(n);
    // There are 6^n possible labelings. n <= 7 so 6^7 = 279936, which is fine.
    // We can also use 0..5 for labels 1..6.
    function<void(int)> dfs_labels = [&](int idx) {
        if (idx == n) {
            // For this labeling, find the maximum number of edges we can select
            // compatible with the domino constraints.
            // m <= 21, so we can iterate over all subsets of edges? 2^21 = 2M, too large for each labeling.
            // Better: For each labeling, the problem reduces to maximum matching in a bipartite graph? 
            // Alternatively, since m <= 21 is small but 2^21 * 6^7 is too big.
            // However, we can use maximum independent set on conflict graph of size m.
            // But there is a simpler way: for a given labeling, each edge corresponds to a domino type (a,b).
            // We just need to pick the maximum subset of edges such that no two edges use the same domino type.
            // This is exactly the problem: given edges with colors (domino types), pick max subset with distinct colors.
            // The colors are among 21 types. We want max edges with distinct colors.
            // This is simply the number of distinct colors used by at least one edge? No, because multiple edges might have the same color, and we can only pick one of them.
            // So the maximum is the number of distinct colors present in the edge set.
            // Wait, is it that simple? Yes, if we can pick at most one edge per domino type.
            // For a fixed labeling, each edge gets a domino type (min(label[u], label[v]), max(...)).
            // We can pick at most one edge per domino type.
            // The maximum number of edges we can pick is exactly the number of distinct domino types that appear among the edges.
            // Because for each distinct type, we can pick exactly one edge that realizes it.
            // There is no other constraint. So we just count distinct domino types.
            // Let's verify: In sample 4, complete graph K7 with 21 edges, output 16. 
            // With n=7 vertices and 6 labels, some edge pairs will collide. Maximum distinct types achievable is 16.
            // So we just need to maximize the number of distinct domino types induced by the edges.

            vector<bool> seen(7*7, false); // for dominoes (a,b) with 1<=a<=b<=6, map to index.
            int cnt = 0;
            for (int i = 0; i < m; ++i) {
                int u = edges[i].first;
                int v = edges[i].second;
                int a = labels[u];
                int b = labels[v];
                if (a > b) swap(a, b);
                int idx = a*7 + b; // a,b in 1..6, so 7*7=49 size is enough
                if (!seen[idx]) {
                    seen[idx] = true;
                    cnt++;
                }
            }
            best = max(best, cnt);
            return;
        }
        for (int c = 1; c <= 6; ++c) {
            labels[idx] = c;
            dfs_labels(idx + 1);
        }
    };

    dfs_labels(0);
    cout << best << "\n";
    return 0;
}
